public abstract class ThresholdAlert implements AlertRule {
    // Store immutable shared threshold and expose it to subclasses safely.
}

public final class HighAlert extends ThresholdAlert {
    public HighAlert(int threshold) { /* call super */ }
    public boolean matches(int reading) { throw new UnsupportedOperationException(); }
}

public final class LowAlert extends ThresholdAlert {
    public LowAlert(int threshold) { /* call super */ }
    public boolean matches(int reading) { throw new UnsupportedOperationException(); }
}

import java.util.List;
public final class RuleSet {
    public RuleSet(List<AlertRule> rules) { /* take ownership safely */ }
    public int matchingRules(int reading) { throw new UnsupportedOperationException(); }
}
